(6652920, 994115, 94265, '<td valign="top">A bit noisy on the birds but very cute nonetheless, nice composition.</td>', 'A bit noisy on the birds but very cute nonetheless, nice composition.', '2012-01-23 11:59:13.000000', NULL, 1),
(6652929, 994493, 94265, '<td valign="top">This one sadly isn''t a high scorer for me; it''s far too smoothed-out, you''ve lost all skin detail and the fur is mostly a blur. The beauty spot on her back is really distracting too. I don''t personally feel that background was a good choice and the contrast has lost the details of her hair too. The composition is fine, the styling is nice and the light looks Ok; I think with a sharper focus and less softening, this could have been great.</td>', 'This one sadly isn''t a high scorer for me; it''s far too smoothed-out, you''ve lost all skin detail and the fur is mostly a blur. The beauty spot on her back is really distracting too. I don''t personally feel that background was a good choice and the contrast has lost the details of her hair too. The composition is fine, the styling is nice and the light looks Ok; I think with a sharper focus and less softening, this could have been great.', '2012-01-23 12:04:42.000000', NULL, 1),
